/* 本地轻量轮播 */
window.Swiper=function(sel,opt){var r=document.querySelector(sel);if(!r)return;var s=r.querySelectorAll(".slide"),i=0;if(!s.length)return;s.forEach(function(x,n){x.style.display=n===0?"flex":"none"});setInterval(function(){s[i].style.display="none";i=(i+1)%s.length;s[i].style.display="flex"},(opt&&opt.autoplay&&opt.autoplay.delay)||4500)};